const results = [];

for (const item of $input.all()) {

  // Parse AI Agent output
  const email = JSON.parse(item.json.output);

  results.push({
    json: {
      subject: email.subject,
      body: email.body,

      // Optional: Save metadata from the form
      purpose: item.json["Email Purpose"] || "",
      recipient_name: item.json["Recipient Name"] || "",
      recipient_email: item.json["Recipient Email"] || "",
      tone: item.json["Tone"] || "",
      email_length: item.json["Email Length"] || "",
      language: item.json["Language"] || "",
      additional_notes: item.json["Additional Notes"] || "",

      // Timestamp
      generated_at: new Date().toLocaleString("en-IN", {
        timeZone: "Asia/Kolkata"
      })
    }
  });

}

return results;

